package com.makers.loans.controller;
import com.makers.loans.dto.*; import com.makers.loans.service.LoanService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") public class AdminController {private final LoanService service; public AdminController(LoanService service){this.service=service;} @GetMapping("/loans") public List<LoanResponse> all(){return service.findAll();} @PatchMapping("/loans/{id}/status") public LoanResponse status(@PathVariable Long id,@Valid @RequestBody StatusRequest r){if(r.status()==com.makers.loans.entity.LoanStatus.PENDING) throw new IllegalArgumentException("El administrador debe elegir aprobado o rechazado"); return service.changeStatus(id,r.status());}}
